import unittest

from assets import asset_key


class AssetKeyTests(unittest.TestCase):
    def test_normalizes_name_and_builds_storage_key(self):
        self.assertEqual(
            asset_key("  Summer  Sale---2025 ", 3),
            "assets/v3/summer_sale_2025.bin",
        )
        self.assertEqual(asset_key("A\tB\nC", 1), "assets/v1/a_b_c.bin")
        self.assertEqual(asset_key("Café/RAW+2", 7), "assets/v7/café/raw+2.bin")

    def test_rejects_invalid_revisions(self):
        for revision in (0, -1, True, False, 1.5, "2", None):
            with self.subTest(revision=revision):
                with self.assertRaises(ValueError):
                    asset_key("photo", revision)

    def test_rejects_invalid_names(self):
        with self.assertRaises(ValueError):
            asset_key("   ", 1)
        with self.assertRaises(TypeError):
            asset_key(None, 1)


if __name__ == "__main__":
    unittest.main()
